static int capiminor_add_ack ( struct capiminor * mp , u16 datahandle ) { struct ackqueue_entry * n ; if ( unlikely ( ! n ) ) { printk ( KERN_ERR "capi: alloc datahandle failed\n" ) ; return - 1 ; } n -> datahandle = datahandle ; INIT_LIST_HEAD ( & n -> list ) ; spin_lock_bh ( & mp -> ackqlock ) ; list_add_tail ( & n -> list , & mp -> ackqueue ) ; mp -> nack ++ ; spin_unlock_bh ( & mp -> ackqlock ) ; return 0 ; } 